<template>
  <section class="order-shipping" aria-labelledby="order-shipping-title">
    <h2 id="order-shipping-title">Vận chuyển &amp; theo dõi</h2>
    <p v-if="loading" role="status">Đang tải thông tin vận chuyển…</p><div v-if="error" role="alert"><p>{{ error }}</p><button class="button button-outline" type="button" :disabled="busy" @click="load">Tải lại vận chuyển</button></div><p v-if="success" role="status">{{ success }}</p>
    <template v-if="data">
      <p v-if="data.checkoutBound" class="shipping-context">GHN · môi trường thử nghiệm. Phí và kiện đã được người mua xác nhận khi đặt hàng. gian hàng xác nhận đơn trước khi tạo vận đơn; COD chưa được coi là đã thu hoặc quyết toán.</p>
      <p v-else class="shipping-context">GHN · môi trường thử nghiệm. Chưa có hợp đồng xác nhận thanh toán/COD để tạo vận đơn. Lựa chọn thử nghiệm không thay đổi phí hoặc tổng tiền trên đơn hiện tại.</p>
      <template v-if="data.shipment">
        <dl class="shipping-facts"><div><dt>Trạng thái vận chuyển</dt><dd><strong>{{ label(data.shipment.state) }}</strong></dd></div><div v-if="data.shipment.trackingCode"><dt>Mã vận đơn GHN</dt><dd>{{ data.shipment.trackingCode }}</dd></div><div v-if="data.selection"><dt>Dịch vụ</dt><dd>{{ data.selection.serviceName }}</dd></div><div><dt>Đối chiếu gần nhất</dt><dd>{{ time(data.shipment.lastSyncAt) || 'Chưa đối chiếu thành công' }}</dd></div></dl>
        <ol v-if="data.shipment.events.length" class="shipment-timeline" aria-label="Sự kiện vận chuyển thực tế"><li v-for="(event, i) in data.shipment.events" :key="i"><strong>{{ label(event.state) }}</strong><time :datetime="event.eventAt + 'Z'">{{ time(event.eventAt) }}</time><span>{{ event.source === 'WEBHOOK' ? 'GHN · callback trạng thái' : 'GHN · đối chiếu API' }}</span></li></ol><p v-else>Chưa có sự kiện trạng thái được xác minh từ GHN.</p>
        <p class="shipping-context">Theo dõi bằng sự kiện của hãng; hiện không có tọa độ GPS người giao hàng.</p>
        <button v-if="!buyer" class="button button-outline" type="button" :disabled="busy" @click="action('sync')">{{ busy ? 'Đang đối chiếu…' : 'Đối chiếu GHN' }}</button>
        <button v-if="seller && data.shipment.state === 'WAITING_PICKUP'" class="button button-outline" type="button" :disabled="busy" @click="action('cancel')">Hủy vận đơn trước lấy hàng</button>
      </template>
      <p v-else>Chưa có vận đơn. Các bước giao hàng sẽ xuất hiện khi có sự kiện thật từ đơn vị vận chuyển.</p>
      <details v-if="seller && !data.shipment && editable && !data.checkoutBound" class="shipping-preparation" open>
        <summary>Chuẩn bị kiện hàng</summary><p>Nhập số đo của toàn kiện đã đóng gói. Không dùng chiều cao cây hoặc số đo ước lượng. Tích hợp hiện hỗ trợ một kiện dưới 20 kg.</p>
        <form :aria-busy="busy" @submit.prevent="saveParcel">
          <fieldset :disabled="busy"><div class="parcel-fields"><div v-for="f in parcelFields" :key="f.key"><label :for="'parcel-' + f.key">{{ f.label }}</label><input :id="'parcel-' + f.key" v-model.number="parcel[f.key]" type="number" min="1" :max="f.max" step="1" required/></div></div>
          <label class="parcel-consent"><input v-model="parcel.carrierAcceptedGoods" type="checkbox"/>Tôi đã đối chiếu chính sách GHN và có xác nhận loại hàng/đóng gói được hãng chấp nhận, kể cả cây sống hoặc hàng dễ vỡ nếu có.</label>
          <button class="button button-outline" type="submit" :disabled="busy">{{ busy ? 'Đang lưu kiện hàng…' : 'Lưu kiện hàng' }}</button></fieldset>
        </form>
      </details>
      <div v-if="buyer && !data.shipment && editable && !data.checkoutBound" class="shipping-quotes">
        <h3>Chọn dịch vụ thử nghiệm</h3><p v-if="!data.parcel">Gian hàng cần lưu số đo kiện hàng trước khi tính phí.</p><button class="button button-outline" type="button" :disabled="busy || !data.parcel" @click="fetchQuotes">{{ busy ? 'Đang lấy báo phí…' : 'Tính lại phí GHN thử nghiệm' }}</button>
        <fieldset v-if="quotes.length" :disabled="busy"><legend>Báo phí từ GHN thử nghiệm · không áp dụng để thanh toán</legend><label v-for="quote in quotes" :key="quote.id" class="shipping-quote"><input v-model="selected" type="radio" :value="quote.id" name="shipping-quote"/><span>{{ quote.serviceName }}<small>Hết hạn: {{ time(quote.expiresAt) }}</small></span><strong>{{ money(quote.fee) }}</strong></label><button class="button button-primary" type="button" :disabled="busy || !selected" @click="selectQuote">Lưu lựa chọn thử nghiệm</button></fieldset>
      </div>
      <p v-if="data.selection" class="shipping-selection">{{ data.checkoutBound?'Dịch vụ đã xác nhận':'Lựa chọn thử nghiệm' }}: <strong>{{ data.selection.serviceName }} · {{ money(data.selection.fee) }}</strong><template v-if="!data.checkoutBound">. Hết hạn {{ time(data.selection.expiresAt) }}</template>.</p>
      <dl v-if="data.checkoutBound && data.parcel" class="shipping-facts"><div><dt>Kiện đã xác nhận</dt><dd>{{ data.parcel.weightGrams }} g · {{ data.parcel.lengthCm }} × {{ data.parcel.widthCm }} × {{ data.parcel.heightCm }} cm</dd></div><div><dt>Thu hộ tiền hàng</dt><dd>{{ money(data.payment.codAmount) }}</dd></div><div><dt>Phí người nhận trả riêng</dt><dd>{{ money(data.payment.shippingFee) }}</dd></div></dl>
      <div v-if="seller && !data.shipment && editable" class="shipping-create"><button class="button button-primary" type="button" :disabled="busy || !data.canCreate" aria-describedby="shipping-create-blocker" @click="action('shipments')">Tạo vận đơn thử nghiệm</button><p id="shipping-create-blocker">{{ data.canCreate?'Thông tin thu hộ, kiện và tổng tiền đã đủ điều kiện tạo vận đơn thử nghiệm. Chỉ tạo khi đã chuẩn bị bàn giao.':blocker(data.createBlocker) }}</p></div>
    </template>
  </section>
</template>
<script setup>
import {computed, onBeforeUnmount, reactive, ref, watch} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';import {formatPrice} from '../../utils.js';
const props = defineProps({endpoint: {type: String, required: true}, orderId: {type: Number, required: true}, status: String, buyer: Boolean});
const data = ref(null), loading = ref(true), busy = ref(false), error = ref(''), success = ref(''), quotes = ref([]), selected = ref('');let sequence = 0;
const seller = computed(() => props.endpoint === '/seller/orders'), editable = computed(() => ['PENDING', 'CONFIRMED'].includes(props.status));
const parcel = reactive({weightGrams: '', lengthCm: '', widthCm: '', heightCm: '', carrierAcceptedGoods: false, revision: 0});
const parcelFields = [{key: 'weightGrams', label: 'Khối lượng (g)', max: 19999}, {key: 'lengthCm', label: 'Dài (cm)', max: 200}, {key: 'widthCm', label: 'Rộng (cm)', max: 200}, {key: 'heightCm', label: 'Cao (cm)', max: 200}];
const path = () => props.endpoint + '/' + props.orderId + '/shipping';
const labels = {CREATING: 'Đang gửi yêu cầu tạo', UNKNOWN: 'Cần đối chiếu với GHN', WAITING_PICKUP: 'Chờ lấy hàng', PICKED_UP: 'Đã lấy hàng', IN_TRANSIT: 'Đang vận chuyển', OUT_FOR_DELIVERY: 'Đang giao hàng', DELIVERY_FAILED: 'Giao hàng chưa thành công', DELIVERED: 'Giao thành công', RETURN_REQUESTED: 'Chờ hoàn về người gửi', RETURNING: 'Đang hoàn về', RETURN_FAILED: 'Hoàn hàng chưa thành công', RETURNED: 'Đã hoàn về', CANCELLED: 'Đã hủy vận đơn', EXCEPTION: 'Sự cố cần đối chiếu', LOST: 'Thất lạc', DAMAGED: 'Hư hỏng', DISPOSED: 'Đã tiêu hủy'};
const label = state => labels[state] || 'Trạng thái cần đối chiếu';const money = amount => formatPrice(amount) + ' ₫';
const blocker=code=>({ORDER_NOT_READY:'Cần gian hàng xác nhận đơn trước khi tạo vận đơn.',COD_ACCOUNT_REQUIRED:'Quản trị viên chưa xác nhận quyền thu hộ COD của tài khoản GHN thử nghiệm.',PAYMENT_CONTRACT_REQUIRED:'Đơn cũ chưa có hợp đồng thanh toán/COD xác thực.',SHIPPING_NOT_CONFIGURED:'GHN thử nghiệm chưa được cấu hình.',SELLER_APPROVAL_REQUIRED:'Gian hàng chưa đủ điều kiện giao nhận.'}[code]||'Thông tin giao nhận hoặc thanh toán cần đối chiếu. Tải lại đơn trước khi xử lý.');
function time(value) {if (!value) return ''; return new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short'}).format(new Date(/Z|[+]\d\d:\d\d$/.test(value) ? value : value + 'Z'));}
async function load() {const ticket = ++sequence; loading.value = true; error.value = ''; try {const result = await request(path()); if (ticket === sequence) {data.value = result; if (result.parcel) Object.assign(parcel, result.parcel);}} catch (e) {if (ticket === sequence) error.value = e.message;} finally {if (ticket === sequence) loading.value = false;}}
async function mutate(suffix, method, body, done) {if (busy.value) return;const ticket = sequence, target = path();busy.value = true;error.value = '';success.value = '';try {const result = await request(target + suffix, method, body, false);if (ticket !== sequence) return;await done(result);if (target === path()) success.value = suffix === '/parcel' ? 'Đã lưu số đo kiện hàng.' : suffix === '/selection' ? 'Đã lưu lựa chọn thử nghiệm. Tổng tiền đơn không thay đổi.' : '';}catch (e) {if (ticket === sequence) error.value = e.message;}finally {if (target === path()) busy.value = false;}}
function saveParcel() {return mutate('/parcel', 'PUT', {...parcel}, async result => {Object.assign(parcel, result);quotes.value = [];selected.value = '';await load();});}
function fetchQuotes() {return mutate('/quotes', 'POST', {}, result => {quotes.value = result;selected.value = '';});}
function selectQuote() {return mutate('/selection', 'POST', {quoteId: selected.value}, load);}
function action(name) {if (['cancel', 'shipments'].includes(name) && !window.confirm(name === 'cancel' ? 'Gửi yêu cầu hủy vận đơn GHN thử nghiệm trước khi lấy hàng?' : 'Tạo vận đơn trên GHN thử nghiệm bằng thông tin đã xác nhận?')) return;return mutate('/' + name, 'POST', {}, load);}
watch(() => [props.orderId, props.endpoint, props.status], () => {data.value = null;quotes.value = [];selected.value = '';busy.value = false;load();}, {immediate: true});onBeforeUnmount(() => sequence++);
</script>
<style scoped>
.order-shipping {border-top:1px solid var(--bm-border);margin-top:28px;padding:28px 0 72px;min-width:0;overflow-wrap:anywhere;}.order-shipping h2 {font-size:var(--bm-type-section);margin:0 0 16px;}.order-shipping h3 {font-size:var(--bm-type-subheading);margin:24px 0 12px;}.order-shipping p {max-width:75ch;line-height:1.65;}.shipping-context,.shipping-create p {color:var(--bm-muted);font-size:var(--bm-type-label);}.shipping-facts {display:grid;gap:12px;max-width:720px;margin-block:24px;}.shipping-facts>div {display:flex;justify-content:space-between;gap:24px;}.shipping-facts dt {color:var(--bm-muted);}.shipping-facts dd {margin:0;text-align:right;}
.shipment-timeline {list-style:none;padding:0 0 0 16px;margin:28px 0;max-width:720px;}.shipment-timeline li {position:relative;border-left:1px solid var(--bm-control-border);padding:0 0 24px 24px;display:grid;gap:6px;}.shipment-timeline li::before {content:'';position:absolute;width:10px;height:10px;border-radius:50%;background:var(--bm-forest);left:-5px;top:6px;}.shipment-timeline li:last-child {border-color:transparent;}.shipment-timeline time,.shipment-timeline span {font-size:var(--bm-type-label);color:var(--bm-muted);}
.shipping-preparation {margin-block:28px;}.shipping-preparation summary {font-weight:700;font-size:var(--bm-type-subheading);cursor:pointer;padding-block:12px;}.order-shipping fieldset {border:0;margin:20px 0;padding:0;min-width:0;}.parcel-fields {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;max-width:800px;}.parcel-fields>div {display:grid;gap:8px;}.parcel-fields input {width:100%;min-height:44px;padding:10px 12px;font:inherit;border:1px solid var(--bm-control-border);border-radius:var(--bm-radius-control);background:var(--bm-surface);color:var(--bm-ink);}.parcel-consent {display:flex;align-items:flex-start;gap:12px;max-width:75ch;line-height:1.65;margin-block:20px;}.parcel-consent input {width:20px;height:20px;flex-shrink:0;accent-color:var(--bm-forest);margin-top:4px;}
.shipping-quote {display:flex;align-items:center;gap:12px;padding:16px 0;border-bottom:1px solid var(--bm-border);max-width:720px;}.shipping-quote span {flex:1;min-width:0;}.shipping-quote small {display:block;color:var(--bm-muted);margin-top:4px;}.shipping-quote input {accent-color:var(--bm-forest);width:20px;height:20px;}.shipping-quotes fieldset button {margin-top:20px;}.shipping-create {margin-top:28px;}.order-shipping :focus-visible {outline:3px solid var(--bm-forest);outline-offset:3px;}
@media(max-width:600px) {.parcel-fields {grid-template-columns:1fr 1fr;}.shipping-facts>div {flex-direction:column;gap:4px;}.shipping-facts dd {text-align:left;}.shipping-quote {flex-wrap:wrap;}.order-shipping button {max-width:100%;}}
</style>
